        }
        return ('0000000' + h.toString(16)).slice(-8);
    }
    function segment(el) {
        var tag = el.tagName.toLowerCase();
        var cls = '';
        if (el.classList && el.classList.length > 0) {
            cls = '.' + el.classList[0];
        }
